static u32 _recoveryTestBallTable[]={0x02E50400,0x02E60400,0x02E50400,0x02EC0400,0x02B70400,0x18740400,0x02E70400,0x02C10400,0x02C10400,0x18730400,0x02EA0400,0x02ED0400,0x18720400,0x02E90400};
extern "C" void recoveryEventCommon(u32 value){recoveryPokemon();fadeSet(3,1.0f);fadeCheck(1);soundOpenPlayME(0x3C8,0,0x7F);fadeSet(2,1.0f);fadeCheck(1);heroMovePoolCounter(3,value);}
extern "C" void recoveryEventPC(u32 group,u32 resource,u32 modelResource,u32*parts,u32*motions){
 GSvec rotation;GSvec position={0,10,0};GSmodel*balls[6];FloorBgmMask*mask=floorSound_getBgmMaskObj();GSmodel*model=GSresGetResource(floorGetCurrentGroupID(),modelResource);tagPeopleWork*person=peopleGet(group,resource);HeroData*hero=savedataGetStatus(0,2);u32 count=heroGetPokeomCount();u8 hasPerson=person!=0;
 for(u16 i=0;i<count;i++){balls[i]=floorOpenObject(_recoveryTestBallTable[(u8)revoceryCatchPokemonBall(i)]);GSmodelSetVisibility(balls[i],0);}
 if(hasPerson){GSmodelGetRotation(person->model,&rotation);peopleRotateToTarget(group,resource,floorGetCurrentGroupID(),modelResource,1.0f);peopleMoveCheck(group,resource,1);}if(mask)mask->stopMask();s32 bgm=_recoveryPauseBGM(0x1F4);
 for(u16 i=0;i<count;i++){pokemonAllKaihuku(heroBiosGetPokemonPtr(hero,i));GSpart*part=GSmodelGetPart(model,parts[i]);GSpartGetTransform(part,&position,0,0);GSpartFree(part);GSmodel*ball=balls[i];GSmodelSetPosition(ball,&position);GSmodelSetVisibility(ball,1);_recoveryEventSetSE(0x19);scriptWaitTime(0.5f);}
 for(u32 i=0;i<count;i++)scriptModelSetMotion(modelResource,motions[i],0,0);_recoveryEventSetME(0x3C8,0,0xFF);while(GSmodelIsAnimating(model))GSthreadSwitch();scriptModelSetMotion(modelResource,motions[6],0,1);
 for(u32 i=0;i<count;i++){GSmodel*ball=balls[i];if(ball){GSmodelSetVisibility(ball,0);GSmodelFree(ball);}}scriptWaitTime(0.7f);soundContinueBGMEX(bgm,0x3E8,0);if(hasPerson&&group!=0&&resource!=0x64){peopleRotateToAngle(group,resource,rotation.param2,1.0f);peopleMoveCheck(group,resource,1);}
}
static s32 _recoveryPauseBGM(unsigned long time){return soundPauseBGMEX(time,0);}
static void _recoveryEventSetSE(unsigned long sound){GSsndPlay(sound,0,0);}
void _recoveryEventSetME(unsigned long sound,unsigned long time,unsigned char volume){soundOpenPlayME(sound,time,volume);}
